const at = (axis, a, fixed, y) => (axis === "x" ? [a, y, fixed] : [fixed, y, a]);
const cellsOf = (x0, x1, y0, y1, z0, z1) => { const c = []; for (let x = x0; x <= x1; x++) for (let y = y0; y <= y1; y++) for (let z = z0; z <= z1; z++) c.push([x, y, z]); return c; };
